  snmp
  socat
  sqlmap
  sslscan
  subfinder
  testssl.sh
  theharvester
  traceroute
  trivy
  whatweb
  wpscan
  zmap
  zzuf
)

if command -v apt-get >/dev/null 2>&1; then
  for pkg in "${APT_PKGS[@]}"; do
    dpkg -s "$pkg" >/dev/null 2>&1 || sudo apt-get install -y "$pkg" || true
  done
fi

# ── pip ─────────────────────────────────────────────────

python3 -m pip show boofuzz >/dev/null 2>&1 || python3 -m pip install --user boofuzz
python3 -m pip show droopescan >/dev/null 2>&1 || python3 -m pip install --user droopescan
